import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone


class GetCellMapping(GenericUnixCommand):
    """Command getCellMapping."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Command getCellMapping.

        :param connection: moler connection to device, terminal when command is executed
        :param options: getCellMapping command
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GetCellMapping, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.titles = ""
        self.headers = []
        self.starts = []
        self.headers_col_count = 0
        self._add_list = False
        self._add_dict = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"getCellMapping {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_header(line)
                self._parse_data_row(line)
            except ParsingDone:
                pass
        return super(GetCellMapping, self).on_new_line(line, is_full_line)

    # lcr lnCel pci eutraCelId chBw noRx CaPoolId ULCoMP L1PoolType              L2PoolType                UEC     CELLC   MACCELL MACULTTI   MACDLTTI   TUPU    DL-PHY  UL-PHY
    _re_data_header = re.compile(r"(\s*\S+\s*)+")

    def _parse_header(self, line):
        if 0 == self.headers_col_count and re.search(GetCellMapping._re_data_header, line):
            self.headers = re.split(r"\s+", line)
            self.headers_col_count = len(self.headers)
            raise ParsingDone()

    def _parse_data_row(self, line):
        if self.headers_col_count == len(re.split(r"\s+", line)):
            values = re.split(r"\s+", line)
            lcr_value = values[0]
            lcr = self.headers[0]
            if lcr not in self.current_ret:
                self.current_ret[lcr] = {}
            self.current_ret[lcr][lcr_value] = {}
            for header, value in zip(self.headers, values):
                if header != lcr:
                    self.current_ret[lcr][lcr_value][header] = value
            raise ParsingDone()


